def merge_intervals(intervals):
    """Merge overlapping or touching closed integer intervals.

    Args:
        intervals: list of [start, end] pairs (closed intervals).

    Returns:
        A new list of merged [start, end] pairs sorted by start.

    Raises:
        ValueError: if any interval has start > end.
    """
    normalized = []
    for interval in intervals:
        start, end = interval
        if start > end:
            raise ValueError(
                "invalid interval: start %r > end %r" % (start, end)
            )
        normalized.append([start, end])

    normalized.sort(key=lambda pair: pair[0])

    result = []
    for start, end in normalized:
        if result and start <= result[-1][1]:
            if end > result[-1][1]:
                result[-1][1] = end
        else:
            result.append([start, end])
    return result

